 p=[]
 p.append(item('What is the value of 900 − 36 − 64?',800,'Combine the amounts being subtracted: 36 + 64 = 100. Thus 900 − 36 − 64 = 900 − 100 = 800.','DIG-01',[700,764,836,872],check=900-36-64))
 p.append(item('A calendar week has seven days. How many days are there in five weeks and three days?',38,'Five full weeks contain 5 × 7 = 35 days. Adding the three extra days gives 38 days.','RATE-01',[32,35,40,56],check=5*7+3))
 p.append(item('Which fraction is greatest?','5/6','Use sixths: 1/2 = 3/6 and 2/3 = 4/6. Also 3/4 is less than 5/6 because 18/24 < 20/24, and 4/5 = 24/30 < 25/30. Therefore 5/6 is greatest.','FRAC-01',['1/2','2/3','3/4','4/5']))
 p.append(item('A compass arrow points west. It turns clockwise through a quarter turn. Which direction does it point?','North','A clockwise quarter turn moves west to north. Trace the clockwise order north, east, south, west, north to check the direction.','SPATIAL-02',['East','South','West','South-west']))
 p.append(item('A number has 6 hundreds, 14 tens and 2 ones. What is the number?',742,'Fourteen tens mean 140, not just 14. Add the place values: 600 + 140 + 2 = 742.','DIG-01',[6142,642,724,762],check=600+14*10+2))
 p.append(item('An empty container weighs 180 g. Filled with rice, it weighs 950 g. What is the mass of the rice?',770,'The filled mass includes both container and rice. Remove the container mass: 950 − 180 = 770 g.','RATE-01',[670,730,1130,1170],check=950-180))
 p.append(item('A regular hexagon has six equal sides of length 7 cm. What is its perimeter?', '42 cm','Perimeter is the distance all the way around the shape. Six equal sides of 7 cm give 6 × 7 = 42 cm.','GEO-01',['13 cm','35 cm','49 cm','84 cm'],figure=polygon([(90,120),(150,35),(270,35),(330,120),(270,205),(150,205)],[(210,25,'7 cm')])) )
 p.append(item('The table shows the numbers of visitors. What is the difference between the greatest and least daily numbers?',18,'The greatest number is 53 on Sunday and the least is 35 on Friday. The difference is 53 − 35 = 18 visitors.','DATA-03',[8,12,15,20],check=53-35,figure=table_diagram([['Thu',41],['Fri',35],['Sat',47],['Sun',53]],['Day','Visitors'])))
 p.append(item('A pattern repeats triangle, circle, square, circle. What is the 19th shape?','Square','The repeating block has length 4. Sixteen shapes make four complete blocks, so position 19 is the third shape of the next block: a square.','SEQ-02',['Triangle','Circle','Pentagon','Hexagon']))
 p.append(item('How many small squares must change colour to make exactly half of this grid shaded?',2,'The grid has 3 × 4 = 12 squares. Half is 6, and 4 are already shaded. Shade two more squares.','FRAC-04',[1,3,4,6],check=12//2-4,figure=grid(4,3,[(0,0),(1,0),(0,1),(3,2)])))
 p.append(item('A pack of six pens costs $8.40. A single pen costs $1.60. How much is saved by buying the pack rather than six single pens?','$1.20','Six individual pens cost 6 × $1.60 = $9.60. The pack saves $9.60 − $8.40 = $1.20.','DIG-01',['$0.20','$0.80','$1.40','$2.40']))
 p.append(item('A rectangle has area 96 cm² and width 8 cm. What is its perimeter?', '40 cm','Its length is 96 ÷ 8 = 12 cm. Perimeter is 2 × (12 + 8) = 40 cm. Area and perimeter measure different things.','GEO-02',['20 cm','24 cm','32 cm','48 cm']))
 p.append(item('What is the greatest three-digit multiple of 7?',994,'The greatest three-digit number is 999. Since 7 × 142 = 994 and the next multiple is 1001, the required multiple is 994.','DIV-01',[987,991,997,999],check=max(n for n in range(100,1000) if n%7==0)))
 p.append(item('Nia is 13th in a queue from the front and 18th from the back. How many people are in the queue?',30,'The two counts include Nia twice. Add them and remove one copy: 13 + 18 − 1 = 30 people.','COUNT-04',[29,31,32,33],check=13+18-1))
 p.append(item('A square is divided into four equal smaller squares. One small square is removed from a corner. If a small square has side 3 cm, what is the perimeter of the remaining L shape?', '24 cm','The original 6 cm square has perimeter 24 cm. Removing a corner removes two outside edges of length 3 but exposes two new edges of length 3. The perimeter stays 24 cm.','GEO-01',['18 cm','21 cm','27 cm','30 cm'],figure=polygon([(80,40),(200,40),(200,110),(320,110),(320,180),(80,180)],[(140,25,'3 cm'),(345,145,'3 cm')])) )
 p.append(item('A bag contains 30 counters, all red or yellow. Two fifths are red. How many yellow counters must be removed so that half the counters left are red?',6,'There are 12 red and 18 yellow counters. The red count stays 12. For equal numbers of the colours, reduce yellow to 12 by removing 6.','FRAC-01',[3,5,8,12],check=30-2*(30*2//5)))
 p.append(item('Five consecutive whole numbers have a total of 105. What is the greatest of them?',23,'The middle number is the mean, 105 ÷ 5 = 21. The five numbers are 19,20,21,22,23, so the greatest is 23.','DATA-02',[19,20,21,25],check=105//5+2))
 p.append(item('A train 120 m long travels at 10 m per second. How many seconds pass from its front entering a 180 m tunnel until its back leaves the tunnel?',30,'The front must travel the tunnel length plus the train length: 180 + 120 = 300 m. At 10 m/s that takes 30 seconds.','RATE-04',[12,18,24,36],check=(180+120)//10))
 p.append(item('Two angles of a triangle differ by 20°. The third angle is 70°. What is the smallest angle?',45,'The other two angles sum to 180° − 70° = 110°. Remove the 20° difference to leave twice the smaller: (110 − 20) ÷ 2 = 45°.','GEO-03',[35,40,50,55],check=(180-70-20)//2))
 p.append(item('A password uses two different letters chosen from A, B, C and D, followed by one digit chosen from 2, 4 and 6. How many passwords are possible?',36,'Choose the first letter in 4 ways, the second in 3 ways because it must differ, and the digit in 3 ways. Multiply: 4 × 3 × 3 = 36. Order matters for the letters.','COUNT-01',[12,18,24,48],check=4*3*3))
 p.append(item('A price is increased by 20% and then reduced by 20% of the new price. The final price is $48. What was the original price?','$50','Multiplying by 1.2 then by 0.8 multiplies the original price by 0.96. Thus the original price is 48 ÷ 0.96 = 50 dollars. Check: $50 → $60 → $48.','FRAC-03',['$46.08','$48','$52','$60']))
 p.append(item('The numbers 1 to 8 are put into four pairs, all with the same sum. What is the product of the two numbers paired with 3 and with 5 respectively?',24,'All numbers total 36, so each of the four pairs sums to 9. The partner of 3 is 6, and the partner of 5 is 4. Their product is 6 × 4 = 24.','ALG-02',[15,18,20,30],check=(9-3)*(9-5)))
 p.append(item('A tank can be filled by a tap in 12 minutes or emptied by a drain in 18 minutes. Both operate at constant rates. Starting empty with both open, how long will it take to fill the tank?', '36 minutes','Each minute the tap adds 1/12 of a tank and the drain removes 1/18. The net gain is 1/12 − 1/18 = 1/36 of a tank per minute. Filling therefore takes 36 minutes.','RATE-02',['6 minutes','15 minutes','24 minutes','30 minutes']))
 p.append(item('A cube is painted on all six outer faces and cut into 64 equal small cubes. How many small cubes have paint on exactly one face?',24,'Since 64 = 4³, there are 4 cubes along each edge. On each face, only the central (4−2)² = 4 cubes have exactly one painted face. Six faces give 6 × 4 = 24 such cubes.','SOLID-02',[8,16,32,48],check=6*(4-2)**2,figure=cuboid(4,4,4)))
 p.append(item('The positive integers from 1 to 80 are written down. How many are divisible by 3 or by 5, but not by both?',32,'There are 26 multiples of 3 and 16 multiples of 5. Five multiples of 15 belong to both lists. To exclude them entirely after adding the two counts, subtract them twice: 26 + 16 − 10 = 32.','COUNT-04',[27,31,37,42],check=sum((n%3==0) != (n%5==0) for n in range(1,81))))
 p.append(item('In how many ways can 200 be written as the sum of two or more consecutive positive integers?',2,'For an odd number of terms, that number must be an odd divisor of 200: 5 or 25. Five terms give 38+39+40+41+42; 25 terms would start negative. For an even length k, the average is a half-integer, so k must contain all four factors of 2 in 400: possible k below 20 is 16. It gives 5+6+…+20. Thus there are two ways. Equivalently, test k in k(2a+k−1)=400; positivity forces k≤19 and only k=5,16 work.','SEQ-03',check=sum(k*(2*a+k-1)==400 for a in range(1,201) for k in range(2,20))))
 p.append(item('Move only right or up from S to T on this grid. How many routes pass through neither crossed vertex?',33,'All routes use five right and four up moves: 9 choose 4 = 126. Routes through (2,1) number 3 × 20 = 60; routes through (3,3) number 20 × 3 = 60. Routes through both number 3 × 3 × 3 = 27 and were subtracted twice. Hence 126 − 60 − 60 + 27 = 33.','SPATIAL-01',check=count_routes(5,4,[(2,1),(3,3)]),figure=routes(5,4,[(2,1),(3,3)])))
 p.append(item('A whole number from 1 to 500 is divisible by exactly two of 4, 6 and 9. How many such numbers are there?',42,'Being divisible by both 4 and 9 already forces divisibility by 6, so that pair contributes none. Multiples of 12 but not 36 contribute 41−13=28; multiples of 18 but not 36 contribute 27−13=14. These groups are disjoint, giving 28+14=42.','DIV-02',check=sum(sum(n%d==0 for d in [4,6,9])==2 for n in range(1,501))))
 p.append(item('A rectangle has perimeter 46 cm. Cutting off a square whose side is the shorter side leaves a smaller rectangle with perimeter 28 cm. What was the area of the original rectangle in square centimetres?',126,'Let the original sides be L and W, with L>W. The remaining rectangle has sides L−W and W, so its perimeter is 2L=28 and L=14. Since L+W=23, W=9. The original area is 14×9=126 cm².','GEO-05',check=14*9))
 masks=[m for m in range(16) if not(m&(m<<1))]
 n=sum(sum(v.bit_count() for v in (a,b,c))==5 and not(a&b or b&c) for a,b,c in product(masks,repeat=3))
 p.append(item('Five squares of a 3-row, 4-column board are shaded. No two shaded squares share a side. Rotations and reflections count as different. How many shadings are possible?',18,'Classify by the middle row, writing 1 for shaded. Valid middle rows 0000 and 1001 give no five-square arrangement. Middle rows 1000 and 0001 give 1 each; 0100 and 0010 give 4 each; 1010 and 0101 give 4 each. For example, middle 0100 forbids column 2 above and below; each outer row must choose two nonadjacent squares, either {1,3} or {1,4}, giving 2×2=4. Sum 1+1+4+4+4+4=18.','COUNT-06',check=n,figure=grid(4,3)))
 one=paper('amc',3,p)
 p=[]
 p.append(item('What is 25 × 16?',400,'Group 16 as 4 × 4. Then 25 × 16 = (25 × 4) × 4 = 100 × 4 = 400.','DIG-01',[300,350,425,450],check=25*16))
 p.append(item('A bus has 42 seats. There are 27 passengers seated and no standing passengers. How many seats are empty?',15,'Subtract the occupied seats from all seats: 42 − 27 = 15. Empty seats and occupied seats together make 42.','DIG-01',[13,14,16,19],check=42-27))
 p.append(item('Which length is greatest?','1.09 m','Convert to centimetres: 1.09 m is 109 cm; 1.01 m is 101 cm; 1050 mm is 105 cm; 108 cm stays 108; 990 mm is 99 cm. Thus 109 cm is greatest.','RATE-01',['1.01 m','1050 mm','108 cm','990 mm']))
 p.append(item('A full turn is divided into six equal angles. How many degrees are in each angle?',60,'A full turn measures 360°. Dividing it into six equal parts gives 360 ÷ 6 = 60° per part.','GEO-03',[30,45,90,120],check=360//6))
 p.append(item('The word MATHEMATICS contains 11 letters. How many of those letters are vowels, counting repeated appearances separately?',4,'The vowels in order are A, E, A and I. Repeated letters are counted each time, giving four vowel appearances.','COUNT-01',[3,5,6,7],check=sum(c in 'AEIOU' for c in 'MATHEMATICS')))
 p.append(item('Luca buys two apples at 85 cents each and a pear at $1.30. What is the total cost?','$3.00','Two apples cost 170 cents. Add the pear’s 130 cents: 170+130=300 cents, which is $3.00.','DIG-01',['$2.15','$2.80','$3.15','$3.30']))
 p.append(item('Which number completes the equation 9 × □ = 126?',14,'Find the missing factor by division: 126 ÷ 9 = 14. Check that 9 × 14 = 90 + 36 = 126.','ALG-01',[12,13,15,16],check=126//9))
 p.append(item('A shape is made of five equal squares arranged as shown. If each small square has side 2 cm, what is the area of the shape?', '20 cm²','Each small square has area 2×2=4 cm². There are five such squares with no overlap, so the area is 5×4=20 cm².','GEO-02',['10 cm²','12 cm²','16 cm²','24 cm²'],figure=polygon([(80,20),(140,20),(140,140),(260,140),(260,200),(80,200)])))
 p.append(item('A spinner has eight equal sectors numbered 1 to 8. What is the probability of landing on a number greater than 5?','3/8','The favourable numbers are 6,7,8: three sectors. All eight sectors are equally likely, so the probability is 3/8.','DATA-01',['1/4','1/2','5/8','3/5'],check=str(F(3,8))))
 p.append(item('A clock shows 3:40 pm. What time was it 55 minutes earlier?','2:45 pm','Move back 40 minutes to 3:00 pm, then another 15 minutes to 2:45 pm. The two moves total 55 minutes.','RATE-01',['2:35 pm','2:55 pm','3:15 pm','4:35 pm']))
 p.append(item('A row has alternating red and blue flags, starting and ending with red. There are 14 blue flags. How many flags are there altogether?',29,'Each blue flag lies between red flags. There is one more red flag than blue flags, giving 15 red and 14 blue, or 29 in all.','SEQ-02',[27,28,30,31],check=14*2+1))
 p.append(item('A fraction equals 3/5. Its denominator is 45. What is its numerator?',27,'The denominator was multiplied by 9 to change 5 into 45. Multiply the numerator by the same amount: 3×9=27.','FRAC-01',[15,24,30,35],check=45//5*3))
 p.append(item('A shop has an offer: buy four identical stickers and receive one more free. Each paid sticker costs 60 cents. What is the least cost of obtaining exactly 15 stickers?','$7.20','Each group of five contains four paid stickers. Fifteen stickers form three groups, so pay for 12 stickers. The cost is 12×60=720 cents=$7.20.','ALG-03',['$6.00','$6.60','$7.80','$9.00']))
 p.append(item('Two squares have side lengths 4 cm and 6 cm. What is the difference between their areas?', '20 cm²','The areas are 4²=16 and 6²=36 square centimetres. Their difference is 36−16=20 cm², not the square of the difference of the sides.','GEO-02',['4 cm²','10 cm²','12 cm²','24 cm²']))
 p.append(item('A positive number is divided by 4 and then increased by 9. This gives the same result as dividing the original number by 2. What is the original number?',36,'Half the number exceeds a quarter of it by another quarter. Therefore a quarter of the number equals 9, and the whole number is 36. Check 36÷4+9=18=36÷2.','ALG-01',[18,24,28,72],check=9*4))
 p.append(item('Three different digits from 1, 3, 5 and 7 are used to make a three-digit number. How many of these numbers exceed 500?',12,'The hundreds digit must be 5 or 7: two choices. Then there are three choices for the tens and two for the units. Thus 2×3×2=12.','DIG-02',[6,8,18,24],check=sum(100*a+10*b+c>500 for a,b,c in permutations([1,3,5,7],3))))
 p.append(item('A runner completes 400 m in 80 seconds. At the same constant speed, how far does the runner travel in 3 minutes?', '900 m','The speed is 400÷80=5 metres per second. Three minutes is 180 seconds, so the distance is 5×180=900 m.','RATE-03',['600 m','750 m','1000 m','1200 m']))
 p.append(item('Four whole-number test scores have a median of 8 and a range of 9. The least score is 3. What is their mean?', '7.75','The greatest score is 3+9=12. The two middle scores sum to 2×8=16, whatever their individual values. All four total 3+12+16=31, so their mean is 31÷4=7.75.','DATA-02',['7','7.5','8','8.25']))
 p.append(item('A 12 cm by 8 cm rectangle is divided by joining the midpoints of its sides. What is the area of the central diamond?', '48 cm²','The four corner triangles each have legs 6 cm and 4 cm, so each has area 12 cm². Subtract their total 48 from the rectangle’s 96 to leave 48 cm².','GEO-02',['24 cm²','32 cm²','64 cm²','72 cm²'],figure=svg('<rect x="60" y="35" width="300" height="180" fill="none"/><polygon points="210,35 360,125 210,215 60,125" fill="#86c9c4"/>'+text(210,25,'12 cm')+text(28,130,'8 cm'))))
 p.append(item('A bag has at least one counter of each of four colours. What is the smallest number of counters that must be taken without looking to guarantee that three have the same colour, regardless of the numbers in the bag?',9,'In the worst case the first eight are two of each colour. A ninth counter must match a colour already seen twice, giving three. Eight cannot guarantee this, so nine is the smallest.','LOGIC-03',[7,8,10,12],check=4*2+1))
 p.append(item('A two-digit number is five times the sum of its digits. How many two-digit numbers have this property?',1,'Write the digits a and b. Then 10a+b=5(a+b), so 5a=4b. The only digit possibility with a nonzero is a=4,b=5, giving 45. Hence exactly one number works.','DIG-05',[2,3,4,5],check=sum(n==5*sum(map(int,str(n))) for n in range(10,100))))
 p.append(item('A sequence starts with 2 and 5. Each later term is the sum of the previous two. What is the remainder when the 10th term is divided by 7?',2,'Build the terms: 2,5,7,12,19,31,50,81,131,212. Since 212=7×30+2, the remainder is 2. Working only with remainders gives 2,5,0,5,5,3,1,4,5,2.','SEQ-04',[0,1,3,5],check=212%7))
 p.append(item('A 6 cm cube is cut into identical 2 cm cubes. All the small cubes are placed in a single straight row with faces touching. What is the length of the row?', '54 cm','There are 6÷2=3 small cubes along each original edge, giving 3³=27 small cubes. In one row their lengths add: 27×2=54 cm.','SOLID-01',['18 cm','27 cm','36 cm','72 cm']))
 p.append(item('A positive integer less than 100 is divisible by 6 and has exactly six positive divisors. How many possibilities are there?',2,'A number with six divisors is either p⁵ or p²q for distinct primes. Divisibility by 6 forces primes 2 and 3, so only 2²×3=12 or 3²×2=18 are possible. Thus there are two possibilities. A direct divisor check gives 12: 1,2,3,4,6,12 and 18: 1,2,3,6,9,18.','DIV-01',[1,3,4,5]))
 assert [n for n in range(1,100) if n%6==0 and len(divisors(n))==6]==[12,18]
 p.append(item('A cyclist rides uphill at 12 km/h and returns down the same road at 24 km/h. What is the average speed for the complete journey?', '16 km/h','Choose a 24 km road for easy arithmetic. Uphill takes 2 hours and downhill 1 hour. The total is 48 km in 3 hours, giving 16 km/h. Equal distances do not mean equal times.','RATE-03',['14 km/h','18 km/h','20 km/h','21 km/h']))
 p.append(item('Three different numbers are chosen from 1 to 10. Their sum is 18 and no two of them are consecutive. How many choices are possible?',6,'List by smallest number: with 1, only (1,7,10); with 2, (2,6,10),(2,7,9); with 3, (3,5,10),(3,6,9); with 4, (4,6,8). A smallest number at least 5 would make the minimum total 5+7+9=21. Thus there are six choices.','COUNT-06',check=sum(sum(z)==18 and z[1]>z[0]+1 and z[2]>z[1]+1 for z in combinations(range(1,11),3))))
 sols=[]
 for t,w,o,f,u,r in permutations(range(10),6):
  if t and f and 2*(100*t+10*w+o)==1000*f+100*o+10*u+r:sols.append((1000*f+100*o+10*u+r,100*t+10*w+o))
 p.append(item('In TWO + TWO = FOUR, different letters stand for different digits and T and F are nonzero. Among all solutions, choose the one with the smallest FOUR. What is TWO?',734,'Doubling a three-digit number forces F=1. To minimise FOUR, try O in increasing order. O=0 would force R=0; O=1 repeats F. With O=2 the units give R=4 and the hundreds give T=6 with no carry from tens. Testing W=0,1,2,3,4 either repeats a digit or makes U repeat T; larger W would create a carry. With O=3 the hundreds force T=6 but the units also give R=6, a repetition. O=4 allows T=7 with no hundreds carry and R=8. Testing W from 0 upwards, 0 repeats U, 1 repeats F, 2 makes U=4 repeat O, and 3 gives U=6. Thus the smallest FOUR is 1468, from TWO=734. Check 734+734=1468.','DIG-05',check=min(sols)[1]))
 p.append(item('Squares of whole-number side length x cm are cut from the four corners of an 18 cm by 12 cm sheet. The sides are folded up to form an open box. What is the greatest possible volume in cubic centimetres?',224,'The dimensions are x,18−2x,12−2x. Positive dimensions allow x=1,2,3,4,5. Their volumes are 160,224,216,160,80 cm³ respectively. Therefore the greatest is 224 cm³ at x=2. Testing every allowed integer proves the maximum.','GEO-05',check=max(x*(18-2*x)*(12-2*x) for x in range(1,6))))
 p.append(item('Seven tiles in a row are each labelled 1, 2 or 3. Adjacent tiles must have different labels and the sum of the labels is 14. How many rows are possible?',56,'Let C(n,s,d) count rows of length n, total s and final digit d. A new d can follow either other digit, so C(n,s,d)=sum of C(n−1,s−d,e) for e≠d. Start with C(1,1,1)=C(1,2,2)=C(1,3,3)=1, all other counts zero. For six tiles, counts ending (1,2,3) at totals 11,12,13 are (9,8,3),(11,10,11),(3,8,9). The seven-tile total-14 counts are 8+9=17, 11+11=22, and 9+8=17. Add them: 56. This table method counts each row by its unique last tile.','COUNT-03',check=sum(sum(z)==14 and all(a!=b for a,b in zip(z,z[1:])) for z in product([1,2,3],repeat=7))))
 p.append(item('A rectangle is 18 cm wide and 12 cm high. One line joins its bottom-left corner to the midpoint of its top side. Another joins its top-left corner to the midpoint of its bottom side. What is the area, in square centimetres, of the triangle between these lines and the left side?',27,'Both sloping lines lie in the left 9 cm by 12 cm half-rectangle and are its diagonals. They meet at its centre, 4.5 cm from the left side. The triangle has base 12 cm and perpendicular height 4.5 cm, so its area is 12×4.5÷2=27 cm².','GEO-02',check=27,figure=svg('<rect x="50" y="35" width="324" height="180" fill="white"/><polygon points="50,35 50,215 131,125" fill="#86c9c4"/><path d="M50,215L212,35 M50,35L212,215" fill="none"/>'+text(212,25,'18 cm')+text(23,125,'12 cm'))))
 return [one,paper('amc',4,p)]
